import{c as s,$ as i,Q as o,j as r,g as t,o as n,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Sales & Cashier (Receipts)","description":"Order processing via the POS terminal, sales channel markups, logistics accounting, customer receipts, and craftsman labor time ROI in OmniCraft ERP.","frontmatter":{"title":"Sales & Cashier (Receipts)","description":"Order processing via the POS terminal, sales channel markups, logistics accounting, customer receipts, and craftsman labor time ROI in OmniCraft ERP.","datePublished":"2026-11-15","dateModified":"2026-11-15","order":9},"headers":[],"relativePath":"docs/spaces/production/sales.md","filePath":"docs/spaces/production/sales.md","lastUpdated":1794700800000}'),d={name:"docs/spaces/production/sales.md"},p={id:"sales-pos-terminal-receipts-and-labor-time-roi",tabindex:"-1"};function h(u,e,g,m,f,y){const a=i("DocIcon");return o(),r("div",null,[t("h1",p,[n(a,{name:"sales"}),e[0]||(e[0]=l(" Sales: POS Terminal, Receipts, and Labor Time ROI ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#sales-pos-terminal-receipts-and-labor-time-roi","aria-label":'Permalink to "Sales: POS Terminal, Receipts, and Labor Time ROI"'},"​",-1))]),e[2]||(e[2]=c('<p>In bespoke craftsmanship and custom manufacturing, the moment of sale represents the ultimate validation of the maker&#39;s labor. This is where materialized capital, frozen in finished goods sitting on workshop shelves, transforms into liquid cash flow for the business.</p><p>When sales tracking is handled casually — in paper notebooks, scattered chat messages, or bank notifications — the craftsman inevitably enters a financial blind spot. Delivery expenses are forgotten, the cost of packaging boxes and ribbon goes untracked, profit margins across different sales platforms blur together, and most critically, the maker cannot see which products genuinely sustain the workshop and which merely consume precious working hours.</p><p>The <strong>&quot;Sales&quot;</strong> tab in <strong>OmniCraft ERP</strong> serves as your professional workshop point of sale (POS) terminal. It unites finished goods inventory, packaging material write-offs, Cash Flow ledger transactions, sales distribution channels, and deep labor time ROI analytics into a single atomic transaction.</p><hr><h2 id="top-summary-metrics-the-financial-pulse-of-your-workshop" tabindex="-1">Top Summary Metrics: The Financial Pulse of Your Workshop <a class="header-anchor" href="#top-summary-metrics-the-financial-pulse-of-your-workshop" aria-label="Permalink to &quot;Top Summary Metrics: The Financial Pulse of Your Workshop&quot;">​</a></h2><p>The top toolbar displays three summary metric cards reflecting the total commercial turnover of your enterprise:</p><ul><li><strong>&quot;Revenue&quot; (Green indicator):</strong> total incoming cash flow generated from product sales over the lifetime of the workshop database.</li><li><strong>&quot;Cost Price&quot; (Red indicator):</strong> the actual batch manufacturing cost (raw materials, workshop overhead, labor hours, and packaging) of all units sold.</li><li><strong>&quot;Net Profit&quot; (Accent indicator):</strong> your true financial return — net earnings after deducting batch manufacturing costs and direct shipping expenses.</li></ul><p>Directly below these cards are two primary operational controls:</p><ul><li><strong>&quot;New Sale&quot;:</strong> expands the compact point of sale form to record an incoming transaction.</li><li><strong>&quot;Margin Rating&quot;:</strong> slides open the side analytical drawer showing product time profitability.</li></ul><hr><h2 id="processing-a-transaction-in-the-pos-cashier" tabindex="-1">Processing a Transaction in the POS Cashier <a class="header-anchor" href="#processing-a-transaction-in-the-pos-cashier" aria-label="Permalink to &quot;Processing a Transaction in the POS Cashier&quot;">​</a></h2><p>To register a sale, click the <strong>&quot;New Sale&quot;</strong> button. The cashier form expands with the following parameters:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Product Selection:</strong> the dropdown list isolates items that are physically available in showroom inventory (<code>stock &gt; 0</code>). This eliminates the risk of accidentally recording sales for out-of-stock items.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Sales Channel:</strong> the venue or origin of the deal (such as your personal website, social media, external marketplace, local craft fair, or direct walk-in studio sale).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Sale Date:</strong> an adaptive calendar picker. For sales registered today, the software records the exact system timestamp; for backdated entries, it automatically sets the time to midday (12:00:00).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Quantity:</strong> the number of units sold. The system validates entries against available physical inventory and blocks negative or zero amounts.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Shipping Cost &amp; Payer:</strong> the cost of carrier delivery and clear attribution of who covers the logistics expense.</div></li></ul><p>Once details are set, click <strong>&quot;Sell&quot;</strong>. OmniCraft ERP immediately executes an atomic database transaction and generates a complete digital receipt.</p><hr><h2 id="logistics-economics-two-shipping-modes" tabindex="-1">Logistics Economics: Two Shipping Modes <a class="header-anchor" href="#logistics-economics-two-shipping-modes" aria-label="Permalink to &quot;Logistics Economics: Two Shipping Modes&quot;">​</a></h2><p>Transportation and courier fees represent one of the most common sources of hidden margin leakage in small production studios. OmniCraft ERP cleanly separates product revenues from carrier costs across two distinct modes:</p><ol><li><p><strong>&quot;Client Pays&quot; Mode (Buyer Compensation):</strong></p><ul><li>The customer pays for the product and separately reimburses carrier delivery (e.g., <code>$100</code> for a bag plus <code>$10</code> for courier shipping).</li><li>The Cash Flow ledger records total incoming cash of <code>$110</code> categorized as &quot;Sales&quot;.</li><li>Simultaneously, the ledger records a <code>$10</code> expense categorized as &quot;Delivery&quot; (payment to the courier or postal service).</li><li><em>Impact on Net Profit:</em> zero. Profit is calculated purely from product markup, while your Cash Flow ledger reflects 100% accurate physical cash turnover.</li></ul></li><li><p><strong>&quot;Shop Pays&quot; Mode (Workshop Expense):</strong></p><ul><li>The maker offers free shipping as a promotional incentive or absorbs shipping costs.</li><li>The Cash Flow ledger records incoming revenue for the product price (<code>$100</code>).</li><li>The ledger records an operational expense for shipping (<code>$10</code>).</li><li><em>Impact on Net Profit:</em> negative. The logistics cost is <strong>directly deducted from your net profit</strong> on this transaction.</li></ul></li></ol><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Transaction Economics</span><div class="formula-heading">Net Profit per Sale Factoring Packaging and Logistics</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Net Profit</span><span class="math-op">=</span><span class="math-var">(Selling Price − Unit Batch Cost − Packaging)</span><span class="math-op">×</span><span class="math-var">Quantity</span><span class="math-op">−</span><span class="math-var">Shipping (if paid by workshop)</span></div></div></div><hr><h2 id="managing-sales-channels-and-platform-markups" tabindex="-1">Managing Sales Channels and Platform Markups <a class="header-anchor" href="#managing-sales-channels-and-platform-markups" aria-label="Permalink to &quot;Managing Sales Channels and Platform Markups&quot;">​</a></h2><p>Different sales channels operate under distinct cost structures: online marketplaces charge listing and merchant fees, weekend markets require booth rentals, while your direct website delivers maximum margin.</p><p>To open the sales channel configuration window, click the gear icon next to the channel selector dropdown in the cashier panel.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Channel Title:</strong><br> Sales channel or order source (e.g., &quot;Etsy&quot;, &quot;Personal Website&quot;, &quot;Craft Fair&quot;). </div></li><li><span class="craft-list-bullet"></span><div><strong>Channel Markup Percentage:</strong><br> Percentage markup added to the base retail price to offset commission and transaction fees. </div></li><li><span class="craft-list-bullet"></span><div><strong>Channel Registry:</strong><br> Management list of active sales channels with instant editing and removal. </div></li></ul><h3 id="retail-price-hierarchy-in-omnicraft-erp" tabindex="-1">Retail Price Hierarchy in OmniCraft ERP: <a class="header-anchor" href="#retail-price-hierarchy-in-omnicraft-erp" aria-label="Permalink to &quot;Retail Price Hierarchy in OmniCraft ERP:&quot;">​</a></h3><p>The software resolves the final retail selling price in the cashier using a strict two-tier logic:</p><ol><li><strong>Fixed Channel Price:</strong> if a fixed selling price has been configured for this specific product on a designated channel (e.g., exactly <code>$120</code> for your web store), the system applies that figure directly.</li><li><strong>Dynamic Calculator Formula:</strong> if no fixed price exists, the system takes the unit batch cost, applies the product&#39;s custom markup (or the global space markup), and compounds the channel&#39;s percentage markup.</li></ol><div class="tip custom-block"><p class="custom-block-title">Master&#39;s Insight: Offsetting Marketplace Fees</p><p>Use channel percentage markups to automatically neutralize platform commissions. If an external marketplace takes a 15% transaction fee, set that channel&#39;s markup to <code>+18%</code>. This preserves your target net profit without requiring manual price adjustments for individual products.</p></div><hr><h2 id="digital-sales-receipt-and-client-communication" tabindex="-1">Digital Sales Receipt and Client Communication <a class="header-anchor" href="#digital-sales-receipt-and-client-communication" aria-label="Permalink to &quot;Digital Sales Receipt and Client Communication&quot;">​</a></h2><p>Upon confirming a sale, the software immediately presents a clean digital sales receipt modal. Receipts can also be accessed at any time from the historical sales ledger.</p><p>Key elements of the digital sales receipt:</p><ul><li>Exact date and time of the transaction;</li><li>Sales distribution channel;</li><li>Product title and unit quantity;</li><li>Unit selling price and subtotal;</li><li>Shipping cost and logistics payer breakdown;</li><li>Final grand total due.</li></ul><p>If the Ambassador module is enabled, a tasteful branding watermark featuring the craftsman&#39;s personal referral link is appended to the receipt footer.</p><p>Click <strong>&quot;Copy Receipt&quot;</strong> to transfer the neatly formatted plaintext receipt directly to your clipboard. You can paste it immediately into client conversations on Telegram, WhatsApp, or email, demonstrating high professional standards and transparency.</p><hr><h2 id="sales-ledger-operational-history-and-audit-trail" tabindex="-1">Sales Ledger: Operational History and Audit Trail <a class="header-anchor" href="#sales-ledger-operational-history-and-audit-trail" aria-label="Permalink to &quot;Sales Ledger: Operational History and Audit Trail&quot;">​</a></h2><p>The lower-left quadrant of the screen houses your chronological sales ledger:</p><ul><li><strong>Table Columns:</strong> Date, Channel, Product, Quantity, Net Profit, and Receipt action button (document icon).</li><li><strong>Pagination (20 rows per page):</strong> guarantees smooth UI scrolling and instantaneous response times even when your ledger grows to tens of thousands of customer orders.</li><li><strong>Instant Record Inspection:</strong> clicking the receipt icon in any row displays the historical transaction details, ready for client review or re-copying.</li></ul><hr><h2 id="analytics-product-rating-by-labor-time-roi-profit-per-hour" tabindex="-1">Analytics: Product Rating by Labor Time ROI (Profit Per Hour) <a class="header-anchor" href="#analytics-product-rating-by-labor-time-roi-profit-per-hour" aria-label="Permalink to &quot;Analytics: Product Rating by Labor Time ROI (Profit Per Hour)&quot;">​</a></h2><p>The right side of the screen houses the <strong>&quot;Product Margin Rating by Time ROI&quot;</strong> drawer (opened via the <strong>&quot;Margin Rating&quot;</strong> button).</p><p>Standard business spreadsheets only report absolute profit (for example: <em>&quot;we earned $100 on a leather briefcase and $20 on a keychain&quot;</em>). This creates a dangerous cognitive trap, leading makers to believe that complex, expensive items are always more profitable.</p><p>OmniCraft ERP tracks the true metric of bespoke craftsmanship efficiency — <strong>net profit per hour of workshop labor</strong>.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Economic Analytics</span><div class="formula-heading">Craftsman Labor Time ROI (Net Profit per Hour)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Profit per Hour</span><span class="math-op">=</span><span class="math-var">Total Net Profit across Sold Units</span><span class="math-op">÷</span><span class="math-var">(Total Units Sold × Recipe Labor Benchmark Hours)</span></div></div></div><h3 id="practical-real-world-studio-insights" tabindex="-1">Practical Real-World Studio Insights: <a class="header-anchor" href="#practical-real-world-studio-insights" aria-label="Permalink to &quot;Practical Real-World Studio Insights:&quot;">​</a></h3><p>Consider a real analysis of workshop sales data:</p><ul><li><strong>Travel Duffle Bag:</strong> net profit of <code>$120</code>, but required <code>10</code> hours of assembly. The craftsman&#39;s effective earnings: <code>$12 per hour</code>.</li><li><strong>Classic Belt:</strong> net profit of <code>$40</code>, requiring <code>1</code> hour of work. Effective earnings: <code>$40 per hour</code>.</li><li><strong>Minimalist Cardholder:</strong> net profit of <code>$25</code>, requiring <code>0.3</code> hours (18 minutes) to cut and stitch. Effective earnings: <code>$83 per hour</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Master&#39;s Takeaway</p><p>The Time ROI panel unmasks &quot;hidden time-killers&quot; and highlights the true economic engines of your workshop. If your flagship product yields less return per hour than basic accessories, you must either raise its price in the Calculator or refine your cutting and assembly workflows to reduce labor hours.</p></div><hr><h2 id="summary-matrix-of-operational-and-financial-effects" tabindex="-1">Summary Matrix of Operational and Financial Effects <a class="header-anchor" href="#summary-matrix-of-operational-and-financial-effects" aria-label="Permalink to &quot;Summary Matrix of Operational and Financial Effects&quot;">​</a></h2><p>When you click <strong>&quot;Sell&quot;</strong>, OmniCraft ERP executes an atomic transaction across multiple subsystems:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Subsystem</th><th style="text-align:left;">Executed Operation</th><th style="text-align:left;">Practical Business Impact</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Showroom Inventory</strong></td><td style="text-align:left;">Deducts product stock balance (<code>-X pcs</code>)</td><td style="text-align:left;">Updates active physical shelf counts</td></tr><tr><td style="text-align:left;"><strong>Finished Goods Batches</strong></td><td style="text-align:left;">Depletes earliest batches via FIFO</td><td style="text-align:left;">Locks in historical cost price of sold items</td></tr><tr><td style="text-align:left;"><strong>Raw Materials Warehouse</strong></td><td style="text-align:left;">Deducts linked packaging materials</td><td style="text-align:left;">Boxes, wrapping paper, and tags are consumed</td></tr><tr><td style="text-align:left;"><strong>Cash Flow Ledger</strong></td><td style="text-align:left;">Double-entry: revenue inflow + shipping expense</td><td style="text-align:left;">Delivers exact physical cash accounting</td></tr><tr><td style="text-align:left;"><strong>Sales Log Registry</strong></td><td style="text-align:left;">Logs immutable snapshot of the transaction</td><td style="text-align:left;">Retains permanent historical audit data</td></tr><tr><td style="text-align:left;"><strong>Management Capital</strong></td><td style="text-align:left;">Value transfer: Finished Goods ➔ Liquid Cash + Profit</td><td style="text-align:left;">Expands business liquidity and net worth</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Accounting Mechanics: Why Packaging Deducts Upon Sale</p><p>Packaging materials (custom branded boxes, tissue paper, wax seals, ribbon) are budgeted in the Calculator recipe, but <strong>are not deducted when an item is assembled on the Workbench</strong>. Items remain unpacked in showroom inventory to keep storage boxes clean and pristine. The moment you click <strong>&quot;Sell&quot;</strong>, the software retrieves the linked packaging specification and automatically relieves those materials from warehouse stock.</p></div><div class="warning custom-block"><p class="custom-block-title">Promotional Gifts and 100% Discounted Items</p><p>If you gift an item to an influencer for promotion, present a piece to a friend, or provide a 100% customer discount, <strong>never write it off through inventory adjustment as a shortage</strong>. Always process the transaction through the POS cashier at <code>$0</code>. This ensures the item&#39;s batch cost is accurately recognized in your profit and loss statements as a commercial marketing expense while preserving immaculate FIFO batch integrity.</p></div>',55))])}const k=s(d,[["render",h]]);export{v as __pageData,k as default};
